=== FILE: apb_regs.v ===
`timescale 1ns/1ps
`default_nettype none

// apb_regs: four 32-bit read/write registers behind an APB4 subordinate port.
// Implements interface_spec.md per microarchitecture.md.
//   * Zero wait states: pready tied high.
//   * Access cycle = psel && penable; writes take effect on the rising edge
//     ending the access phase, byte-enabled by pstrb.
//   * Mapped: paddr[1:0] == 0 and paddr[ADDR_WIDTH-1:4] == 0 (0x0..0xC).
//   * Unmapped access: pslverr high, no register update, prdata zero.
//   * prdata and pslverr are zero outside the access phase.
//   * presetn: synchronous, active low; all registers reset to zero.
module apb_regs #(
    parameter ADDR_WIDTH = 8,
    parameter DATA_WIDTH = 32
) (
    input  wire                      pclk,
    input  wire                      presetn,
    input  wire [ADDR_WIDTH-1:0]     paddr,
    input  wire                      psel,
    input  wire                      penable,
    input  wire                      pwrite,
    input  wire [DATA_WIDTH-1:0]     pwdata,
    input  wire [DATA_WIDTH/8-1:0]   pstrb,
    output wire [DATA_WIDTH-1:0]     prdata,
    output wire                      pready,
    output wire                      pslverr
);

    // ------------------------------------------------------------------
    // Transfer qualification and address decode
    // ------------------------------------------------------------------
    wire apb_access = psel & penable;

    wire mapped = (paddr[1:0] == 2'b00) &&
                  (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

    wire wr_access = apb_access &  pwrite & mapped;
    wire rd_access = apb_access & ~pwrite & mapped;

    wire [1:0] idx = paddr[3:2];

    // ------------------------------------------------------------------
    // Byte write mask from pstrb
    // ------------------------------------------------------------------
    wire [DATA_WIDTH-1:0] wmask;

    genvar b;
    generate
        for (b = 0; b < DATA_WIDTH/8; b = b + 1) begin : g_wmask
            assign wmask[8*b +: 8] = {8{pstrb[b]}};
        end
    endgenerate

    // ------------------------------------------------------------------
    // Register file: four separate flops
    // ------------------------------------------------------------------
    reg [DATA_WIDTH-1:0] reg0;
    reg [DATA_WIDTH-1:0] reg1;
    reg [DATA_WIDTH-1:0] reg2;
    reg [DATA_WIDTH-1:0] reg3;

    always @(posedge pclk) begin
        if (!presetn) begin
            reg0 <= {DATA_WIDTH{1'b0}};
            reg1 <= {DATA_WIDTH{1'b0}};
            reg2 <= {DATA_WIDTH{1'b0}};
            reg3 <= {DATA_WIDTH{1'b0}};
        end else if (wr_access) begin
            case (idx)
                2'd0: reg0 <= (reg0 & ~wmask) | (pwdata & wmask);
                2'd1: reg1 <= (reg1 & ~wmask) | (pwdata & wmask);
                2'd2: reg2 <= (reg2 & ~wmask) | (pwdata & wmask);
                2'd3: reg3 <= (reg3 & ~wmask) | (pwdata & wmask);
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Read data: combinational 4:1 mux, zero unless a mapped read access
    // ------------------------------------------------------------------
    wire [DATA_WIDTH-1:0] rmux = (idx == 2'd0) ? reg0 :
                                 (idx == 2'd1) ? reg1 :
                                 (idx == 2'd2) ? reg2 :
                                                 reg3;

    assign prdata  = rd_access ? rmux : {DATA_WIDTH{1'b0}};
    assign pready  = 1'b1;
    assign pslverr = apb_access & ~mapped;

`ifdef FORMAL
    // Design-intent assertions (combinational subset of the planned proof).
    always @(*) begin
        assert (pready == 1'b1);
        if (!apb_access) begin
            assert (prdata == {DATA_WIDTH{1'b0}});
            assert (pslverr == 1'b0);
        end
        if (apb_access && !mapped) begin
            assert (pslverr == 1'b1);
            assert (prdata == {DATA_WIDTH{1'b0}});
        end
        if (apb_access && mapped) begin
            assert (pslverr == 1'b0);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
`timescale 1ns/1ps
`default_nettype none

// Self-checking directed testbench for apb_regs.
// Drives inputs just after the falling edge, samples 1 ns later (well before
// the next rising edge). Every failed check is reported with $error and
// counted; every passing check is counted. Verdict printed once before $finish.
module apb_regs_tb;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;

    integer passed;
    integer failed;
    reg [8*64-1:0] nonce;

    apb_regs #(
        .ADDR_WIDTH(8),
        .DATA_WIDTH(32)
    ) dut (
        .pclk    (pclk),
        .presetn (presetn),
        .paddr   (paddr),
        .psel    (psel),
        .penable (penable),
        .pwrite  (pwrite),
        .pwdata  (pwdata),
        .pstrb   (pstrb),
        .prdata  (prdata),
        .pready  (pready),
        .pslverr (pslverr)
    );

    // Clock: 10 ns period.
    initial begin
        pclk = 1'b0;
        forever #5 pclk = ~pclk;
    end

    // ------------------------------------------------------------------
    // Check helpers
    //   what codes: 1 pready quiet, 2 pslverr quiet, 3 prdata quiet,
    //               4 pslverr access, 5 prdata read access,
    //               6 prdata write access, 7 pready access
    // ------------------------------------------------------------------
    task check1(input got, input expv, input integer what);
        begin
            if (got !== expv) begin
                $error("apb_regs_tb: check %0d failed at %0t: paddr=%h got %b expected %b",
                       what, $time, paddr, got, expv);
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end
        end
    endtask

    task check32(input [31:0] got, input [31:0] expv, input integer what);
        begin
            if (got !== expv) begin
                $error("apb_regs_tb: check %0d failed at %0t: paddr=%h got %h expected %h",
                       what, $time, paddr, got, expv);
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end
        end
    endtask

    task check_quiet;
        begin
            check1(pready, 1'b1, 1);
            check1(pslverr, 1'b0, 2);
            check32(prdata, 32'h0000_0000, 3);
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks. Each transfer: setup cycle, then one access cycle.
    // The task returns during the access cycle; the caller follows with
    // another transfer (back to back) or with idle cycles.
    // ------------------------------------------------------------------
    task apb_write(input [7:0] addr, input [31:0] data, input [3:0] strb, input exp_err);
        begin
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b1;
            paddr   = addr;
            pwdata  = data;
            pstrb   = strb;
            #1;
            check_quiet;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check1(pready, 1'b1, 7);
            check1(pslverr, exp_err, 4);
            check32(prdata, 32'h0000_0000, 6);
        end
    endtask

    task apb_read(input [7:0] addr, input [31:0] exp_data, input exp_err);
        begin
            @(negedge pclk);
            psel    = 1'b1;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = addr;
            pwdata  = 32'hA5A5_A5A5;
            pstrb   = 4'h0;
            #1;
            check_quiet;
            @(negedge pclk);
            penable = 1'b1;
            #1;
            check1(pready, 1'b1, 7);
            check1(pslverr, exp_err, 4);
            check32(prdata, exp_data, 5);
        end
    endtask

    task idle(input integer cycles);
        integer k;
        begin
            for (k = 0; k < cycles; k = k + 1) begin
                @(negedge pclk);
                psel    = 1'b0;
                penable = 1'b0;
                pwrite  = 1'b0;
                paddr   = 8'h04;
                pwdata  = 32'h0000_0000;
                pstrb   = 4'h0;
                #1;
                check_quiet;
            end
        end
    endtask

    task do_reset(input integer cycles);
        integer k;
        begin
            @(negedge pclk);
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'h00;
            pwdata  = 32'h0000_0000;
            pstrb   = 4'h0;
            presetn = 1'b0;
            for (k = 0; k < cycles; k = k + 1) begin
                #1;
                check_quiet;
                @(negedge pclk);
            end
            presetn = 1'b1;
            #1;
            check_quiet;
        end
    endtask

    // ------------------------------------------------------------------
    // Watchdog: a hung run is a failed run.
    // ------------------------------------------------------------------
    initial begin
        #200000;
        $error("apb_regs_tb: timeout");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end

    // ------------------------------------------------------------------
    // Test sequence
    // ------------------------------------------------------------------
    initial begin
        passed  = 0;
        failed  = 0;
        presetn = 1'b0;
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'h00;
        pwdata  = 32'h0000_0000;
        pstrb   = 4'h0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = {64{8'h00}};

        // 1. Reset, then reset values.
        do_reset(3);
        idle(2);
        apb_read(8'h00, 32'h0000_0000, 1'b0);
        apb_read(8'h04, 32'h0000_0000, 1'b0);
        apb_read(8'h08, 32'h0000_0000, 1'b0);
        apb_read(8'h0C, 32'h0000_0000, 1'b0);
        idle(1);

        // 2. Full writes to every register, back to back, then read back back to back.
        apb_write(8'h00, 32'h1122_3344, 4'hF, 1'b0);
        apb_write(8'h04, 32'h5566_7788, 4'hF, 1'b0);
        apb_write(8'h08, 32'h99AA_BBCC, 4'hF, 1'b0);
        apb_write(8'h0C, 32'hDEAD_BEEF, 4'hF, 1'b0);
        apb_read (8'h00, 32'h1122_3344, 1'b0);
        apb_read (8'h04, 32'h5566_7788, 1'b0);
        apb_read (8'h08, 32'h99AA_BBCC, 1'b0);
        apb_read (8'h0C, 32'hDEAD_BEEF, 1'b0);

        // 3. Idle gaps between transfers.
        idle(1);
        apb_write(8'h04, 32'hCAFE_F00D, 4'hF, 1'b0);
        idle(3);
        apb_read (8'h04, 32'hCAFE_F00D, 1'b0);
        idle(1);
        apb_read (8'h00, 32'h1122_3344, 1'b0);
        idle(2);

        // 4. pstrb partial writes.
        apb_write(8'h08, 32'hFFFF_FFFF, 4'b0001, 1'b0);
        apb_read (8'h08, 32'h99AA_BBFF, 1'b0);
        apb_write(8'h08, 32'h0000_0000, 4'b0100, 1'b0);
        apb_read (8'h08, 32'h9900_BBFF, 1'b0);
        apb_write(8'h08, 32'h1234_5678, 4'b1010, 1'b0);
        apb_read (8'h08, 32'h1200_56FF, 1'b0);
        apb_write(8'h08, 32'h0000_0000, 4'b0000, 1'b0);
        apb_read (8'h08, 32'h1200_56FF, 1'b0);
        apb_write(8'h0C, 32'h0000_0000, 4'b1100, 1'b0);
        apb_read (8'h0C, 32'h0000_BEEF, 1'b0);
        apb_write(8'h0C, 32'hFFFF_1234, 4'b0011, 1'b0);
        apb_read (8'h0C, 32'h0000_1234, 1'b0);
        apb_write(8'h00, 32'hABFF_FFFF, 4'b1000, 1'b0);
        apb_read (8'h00, 32'hAB22_3344, 1'b0);
        apb_write(8'h04, 32'h0012_3400, 4'b0110, 1'b0);
        apb_read (8'h04, 32'hCA12_340D, 1'b0);
        idle(1);

        // 5. PSLVERR policy: unmapped writes (misaligned and out of range)
        //    complete with pslverr and change no register.
        apb_write(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h02, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h03, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h05, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h0A, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h0E, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h10, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h14, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h18, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h1C, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'hFC, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'hFF, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_write(8'h10, 32'hFFFF_FFFF, 4'h0, 1'b1);
        apb_read (8'h00, 32'hAB22_3344, 1'b0);
        apb_read (8'h04, 32'hCA12_340D, 1'b0);
        apb_read (8'h08, 32'h1200_56FF, 1'b0);
        apb_read (8'h0C, 32'h0000_1234, 1'b0);

        //    Unmapped reads return zero with pslverr.
        apb_read (8'h01, 32'h0000_0000, 1'b1);
        apb_read (8'h06, 32'h0000_0000, 1'b1);
        apb_read (8'h0B, 32'h0000_0000, 1'b1);
        apb_read (8'h0F, 32'h0000_0000, 1'b1);
        apb_read (8'h10, 32'h0000_0000, 1'b1);
        apb_read (8'h14, 32'h0000_0000, 1'b1);
        apb_read (8'h1C, 32'h0000_0000, 1'b1);
        apb_read (8'hFF, 32'h0000_0000, 1'b1);
        idle(2);

        // 6. Mixed back-to-back writes and reads, mapped and unmapped.
        apb_write(8'h00, 32'h0F0F_0F0F, 4'hF, 1'b0);
        apb_read (8'h00, 32'h0F0F_0F0F, 1'b0);
        apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b1);
        apb_read (8'h00, 32'h0F0F_0F0F, 1'b0);
        apb_read (8'h11, 32'h0000_0000, 1'b1);
        apb_write(8'h04, 32'h7654_3210, 4'hF, 1'b0);
        apb_read (8'h04, 32'h7654_3210, 1'b0);
        idle(2);

        // 7. Reset again: every register returns to zero.
        do_reset(2);
        idle(1);
        apb_read (8'h00, 32'h0000_0000, 1'b0);
        apb_read (8'h04, 32'h0000_0000, 1'b0);
        apb_read (8'h08, 32'h0000_0000, 1'b0);
        apb_read (8'h0C, 32'h0000_0000, 1'b0);
        apb_write(8'h0C, 32'h0000_A5A5, 4'hF, 1'b0);
        apb_read (8'h0C, 32'h0000_A5A5, 1'b0);
        idle(2);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
